/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p %s bytes\\n' | sort && printf '\\nTOOLS\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
try:
 import cv2; print('cv2',cv2.__version__)
except Exception as e: print('no cv2',e)
try:
 import PIL; print('PIL',PIL.__version__)
except Exception as e: print('no PIL',e)
PY"

/bin/bash -lc 'for x in python3 ffmpeg convert magick; do command -v "$x" || true; done; python3 - <<'"'PY'
for m in ['cv2','PIL','numpy','imageio','av']:
 try:
  x=__import__(m); print(m,getattr(x,'__version__','ok'))
 except Exception as e: print(m,'NO',e)
PY"
